using System.Collections.Concurrent;
using System.ComponentModel;
using System.Reflection;

namespace Slint.Generated;

/// <summary>Converts between the types of generated code and the values of <see cref="ComponentInstance"/>.</summary>
/// <remarks>Code generated by <c>slint-compiler -f csharp</c> calls this; you don't need to.</remarks>
[EditorBrowsable(EditorBrowsableState.Never)]
public static class Conversion
{
    private static readonly ConcurrentDictionary<Type, Func<object, object?>> s_toSlint = new();

    internal static class From<T>
    {
        public static Func<object?, T>? Convert;
    }

    /// <summary>Registers the conversions of a generated struct or enum.</summary>
    public static void Register<T>(Func<T, object?> toSlint, Func<object?, T> fromSlint)
        where T : notnull
    {
        s_toSlint[typeof(T)] = value => toSlint((T)value);
        From<T>.Convert = fromSlint;
    }

    /// <summary>Registers the conversion of a model property with rows of <typeparamref name="T"/>.</summary>
    public static void RegisterModel<T>() =>
        From<Model<T>>.Convert = value => value switch
        {
            Model<T> model => model,
            Model<object?> model => new ConvertedModel<T>(model),
            _ => throw new InvalidCastException($"Can't convert {value?.GetType().Name ?? "null"} to Model<{typeof(T).Name}>"),
        };

    /// <summary>Converts a value returned by <see cref="ComponentInstance"/> to <typeparamref name="T"/>.</summary>
    public static T FromSlint<T>(object? value) => ValueConverter.ConvertTo<T>(value);

    /// <summary>Returns the field <paramref name="name"/> of <paramref name="value"/> as <typeparamref name="T"/>, or <paramref name="fallback"/> if there's none.</summary>
    public static T Field<T>(Struct value, string name, T fallback) =>
        value.TryGetValue(name, out var field) ? FromSlint<T>(field) : fallback;

    /// <summary>Converts <paramref name="value"/> for <see cref="ComponentInstance"/>.</summary>
    public static object? ToSlint<T>(T value) => value;

    internal static bool TryToSlint(object value, out object? converted)
    {
        if (s_toSlint.TryGetValue(value.GetType(), out var convert))
        {
            converted = convert(value);
            return true;
        }
        converted = null;
        return false;
    }
}

/// <summary>A typed view of a model that Slint created.</summary>
internal sealed class ConvertedModel<T>(Model<object?> rows) : Model<T>
{
    public override int RowCount => rows.RowCount;

    public override T RowData(int row) => Conversion.FromSlint<T>(rows.RowData(row));

    public override void SetRowData(int row, T value) => rows.SetRowData(row, value);

    private protected override nint ToNativeValue() => ((INativeModel)rows).ToNativeValue();
}

/// <summary>
/// The name in the <c>.slint</c> file of a generated property, of the callback that an <c>On</c> method sets, or of a global,
/// for code that matches members by name, such as the source generator of <see cref="SlintViewModelAttribute"/>.
/// </summary>
[EditorBrowsable(EditorBrowsableState.Never)]
[AttributeUsage(AttributeTargets.Property | AttributeTargets.Method | AttributeTargets.Class)]
public sealed class SlintNameAttribute(string name) : Attribute
{
    /// <summary>The name in the <c>.slint</c> file.</summary>
    public string Name { get; } = name;
}

/// <summary>The members that generated code expects a component or global to have.</summary>
/// <param name="Properties">The properties and their types.</param>
/// <param name="Callbacks">The callbacks.</param>
/// <param name="Functions">The functions.</param>
[EditorBrowsable(EditorBrowsableState.Never)]
public sealed record ExpectedApi(
    IReadOnlyDictionary<string, ValueType> Properties,
    IReadOnlyList<string> Callbacks,
    IReadOnlyList<string> Functions);

/// <summary>Loads the <c>.slint</c> file of generated code, and checks that it still matches the generated code.</summary>
[EditorBrowsable(EditorBrowsableState.Never)]
public static class GeneratedApi
{
    private static string? s_baseDirectory;

    /// <summary>The build's project directory, for the absolute paths of generated code with embedded files.</summary>
    private static string? s_projectDirectory;

    /// <summary>The files that the assemblies embed, at their paths below <see cref="BaseDirectory"/>.</summary>
    private static KeyValuePair<string, byte[]>[]? s_embeddedFiles;

    /// <summary>
    /// The directory that generated code loads <c>.slint</c> files with relative paths from:
    /// the application directory, on Android the directory where <c>SlintActivity</c> extracts them,
    /// and with files that the assemblies embed, a directory that exists only for the compiler, which reads them from memory.
    /// </summary>
    public static string BaseDirectory
    {
        get => s_baseDirectory ??= FindEmbeddedFiles() ?? AppContext.BaseDirectory;
        internal set => s_baseDirectory = value;
    }

    /// <summary>
    /// The prefix of the resources that <c>Slint.targets</c> embeds with <c>SlintEmbedFiles</c> and in the browser,
    /// before the path relative to the project.
    /// </summary>
    private const string EmbeddedResourcePrefix = "slint:";

    /// <summary>
    /// Reads the embedded files, and returns the directory they're below,
    /// which is as many levels deep as the paths go up with <c>../</c>; or null without embedded files.
    /// </summary>
    private static string? FindEmbeddedFiles()
    {
        var assemblies = AppDomain.CurrentDomain.GetAssemblies().Where(a => !a.IsDynamic).ToList();
        var files = (
            from assembly in assemblies
            from name in assembly.GetManifestResourceNames()
            where name.StartsWith(EmbeddedResourcePrefix, StringComparison.Ordinal)
            select (assembly, name, path: name[EmbeddedResourcePrefix.Length..])).ToList();
        if (files.Count == 0)
        {
            return null;
        }
        var depth = files.Max(file => ParentLevels(file.path));
        var root = Path.Combine([AppContext.BaseDirectory, "slint-embedded", .. Enumerable.Repeat("_", depth)]);
        s_embeddedFiles = files.Select(file =>
        {
            using var resource = file.assembly.GetManifestResourceStream(file.name)!;
            using var data = new MemoryStream();
            resource.CopyTo(data);
            return KeyValuePair.Create(Path.GetFullPath(Path.Combine(root, file.path)), data.ToArray());
        }).ToArray();
        foreach (var assembly in assemblies)
        {
            using var resource = assembly.GetManifestResourceStream("slint-project-directory");
            if (resource != null)
            {
                s_projectDirectory = new StreamReader(resource).ReadToEnd().Trim();
                break;
            }
        }
        return Path.GetFullPath(root);
    }

    private static int ParentLevels(string path)
    {
        var levels = 0;
        while (path.AsSpan(levels * 3).StartsWith("../"))
        {
            levels++;
        }
        return levels;
    }

    /// <summary>Maps an absolute path of the build machine to its embedded file.</summary>
    private static string EmbeddedPath(string path) =>
        s_projectDirectory == null || !Path.IsPathFullyQualified(path)
            ? path
            : Path.GetFullPath(Path.Combine(BaseDirectory, Path.GetRelativePath(s_projectDirectory, path)));

    /// <summary>
    /// Writes the embedded files below <paramref name="directory"/> to a directory of the user's temporary files, and returns it,
    /// since the compiler reads bundled translations from the file system only.
    /// </summary>
    private static string WriteEmbeddedDirectory(string directory)
    {
        var prefix = Path.TrimEndingDirectorySeparator(directory) + Path.DirectorySeparatorChar;
        var build = Assembly.GetEntryAssembly()?.ManifestModule.ModuleVersionId.ToString("N") ?? "shared";
        var target = Path.Combine(Path.GetTempPath(), "slint-dotnet", build);
        foreach (var (path, data) in s_embeddedFiles!.Where(file => file.Key.StartsWith(prefix, StringComparison.Ordinal)))
        {
            var file = Path.Combine(target, path[prefix.Length..]);
            Directory.CreateDirectory(Path.GetDirectoryName(file)!);
            File.WriteAllBytes(file, data);
        }
        return target;
    }

    /// <summary>Compiles <paramref name="path"/>, throwing with the diagnostics if it has errors.</summary>
    public static CompilationResult Load(
        string path,
        string? style,
        IReadOnlyList<string>? includePaths = null,
        IReadOnlyDictionary<string, string>? libraryPaths = null,
        string? translationDomain = null,
        string? bundledTranslationsPath = null,
        DefaultTranslationContext defaultTranslationContext = DefaultTranslationContext.ComponentName)
    {
        _ = BaseDirectory;
        if (s_embeddedFiles != null)
        {
            path = Path.GetFullPath(path);
            includePaths = includePaths?.Select(EmbeddedPath).ToList();
            libraryPaths = libraryPaths?.ToDictionary(entry => entry.Key, entry => EmbeddedPath(entry.Value));
            bundledTranslationsPath = bundledTranslationsPath == null ? null : WriteEmbeddedDirectory(EmbeddedPath(bundledTranslationsPath));
        }
        using var compiler = new Compiler();
        if (s_embeddedFiles != null)
        {
            compiler.SetEmbeddedFiles(s_embeddedFiles);
        }
        if (translationDomain != null)
        {
            compiler.TranslationDomain = translationDomain;
        }
        if (bundledTranslationsPath != null)
        {
            compiler.BundledTranslationsPath = bundledTranslationsPath;
        }
        compiler.DefaultTranslationContext = defaultTranslationContext;
        if (style != null)
        {
            compiler.Style = style;
        }
        if (includePaths is { Count: > 0 })
        {
            compiler.IncludePaths = includePaths;
        }
        if (libraryPaths is { Count: > 0 })
        {
            compiler.LibraryPaths = libraryPaths;
        }
        var result = compiler.BuildFromPath(path);
        if (result.HasErrors)
        {
            var diagnostics = string.Join("\n", result.Diagnostics.Where(d => d.Level == DiagnosticLevel.Error));
            result.Dispose();
            throw new SlintException($"Failed to compile {path}:\n{diagnostics}");
        }
        return result;
    }

    /// <summary>
    /// Creates the component <paramref name="name"/>,
    /// after checking it and <paramref name="globals"/> against the API that the code was generated for.
    /// </summary>
    public static ComponentInstance Create(
        CompilationResult result,
        string generatedFile,
        string name,
        ExpectedApi component,
        IReadOnlyDictionary<string, ExpectedApi> globals)
    {
        using var definition = Check(result, generatedFile, name, component, globals);
        return definition.Create();
    }

    /// <summary>
    /// Like <see cref="Create"/>, but the component reloads <paramref name="path"/> when it changes,
    /// see <see cref="ComponentInstance.CreateLive"/>.
    /// Without live reload in the native library, warns and creates the component once.
    /// </summary>
    public static ComponentInstance CreateLive(
        CompilationResult result,
        string path,
        string? style,
        string generatedFile,
        string name,
        ExpectedApi component,
        IReadOnlyDictionary<string, ExpectedApi> globals,
        IReadOnlyList<string>? includePaths = null,
        IReadOnlyDictionary<string, string>? libraryPaths = null,
        string? translationDomain = null,
        string? bundledTranslationsPath = null,
        DefaultTranslationContext defaultTranslationContext = DefaultTranslationContext.ComponentName)
    {
        using var definition = Check(result, generatedFile, name, component, globals);
        if (!ComponentInstance.LiveReloadAvailable)
        {
            Console.Error.WriteLine($"Slint: the native library can't reload .slint files, so {name} won't reload");
            return definition.Create();
        }
        return ComponentInstance.CreateLive(
            path, name, style, includePaths, libraryPaths, translationDomain, bundledTranslationsPath, defaultTranslationContext);
    }

    private static ComponentDefinition Check(
        CompilationResult result,
        string generatedFile,
        string name,
        ExpectedApi component,
        IReadOnlyDictionary<string, ExpectedApi> globals)
    {
        var definition = result.Component(name)
            ?? throw new SlintException($"{generatedFile} is out of date: the .slint file no longer exports '{name}'");
        var problems = new List<string>();
        Compare(name, component, definition.Properties, definition.Callbacks, definition.Functions, problems);
        foreach (var (global, expected) in globals)
        {
            var properties = definition.GlobalProperties(global);
            if (properties == null)
            {
                problems.Add($"there's no global '{global}'");
                continue;
            }
            Compare(global, expected, properties, definition.GlobalCallbacks(global)!, definition.GlobalFunctions(global)!, problems);
        }
        if (problems.Count > 0)
        {
            definition.Dispose();
            throw new SlintException($"{generatedFile} is out of date; regenerate it:\n" + string.Join("\n", problems));
        }
        return definition;
    }

    private static void Compare(
        string owner,
        ExpectedApi expected,
        IReadOnlyDictionary<string, ValueType> properties,
        IReadOnlyList<string> callbacks,
        IReadOnlyList<string> functions,
        List<string> problems)
    {
        var actualProperties = properties.ToDictionary(p => Normalize(p.Key), p => p.Value);
        foreach (var (property, type) in expected.Properties)
        {
            if (!actualProperties.TryGetValue(property, out var actual))
            {
                problems.Add($"'{owner}' has no property '{property}'");
            }
            else if (actual != type)
            {
                problems.Add($"property '{property}' of '{owner}' is {actual}, not {type}");
            }
        }
        var actualCallbacks = callbacks.Select(Normalize).ToHashSet();
        problems.AddRange(expected.Callbacks.Where(c => !actualCallbacks.Contains(c)).Select(c => $"'{owner}' has no callback '{c}'"));
        var actualFunctions = functions.Select(Normalize).ToHashSet();
        problems.AddRange(expected.Functions.Where(f => !actualFunctions.Contains(f)).Select(f => $"'{owner}' has no function '{f}'"));
    }

    /// <summary>Matches <c>normalize_identifier</c> in <c>internal/compiler/names.rs</c>.</summary>
    private static string Normalize(string name) =>
        name.Length == 0 ? name : (name[0] == '-' ? '_' : name[0]) + name[1..].Replace('_', '-');
}
